-- Description: Current active relationship for LNK_BILLMASTER_BILLABLECHARGE using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_BILLMASTER_BILLABLECHARGE_HKEY AS LNK_BILLMASTER_BILLABLECHARGE_HKEY,
    l.BILLMASTER_HKEY AS BILLMASTER_HKEY,
    l.BILLABLECHARGE_HKEY AS BILLABLECHARGE_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls.DATELASTSYNC

    ROW_NUMBER() OVER (
        PARTITION BY l.BILLMASTER_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls.DATELASTSYNC
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_billmaster_billablecharge') }} l
INNER JOIN {{ ref('lks_bh1_billmaster_billablecharge_curr') }} ls
    ON l.LNK_BILLMASTER_BILLABLECHARGE_HKEY = ls.LNK_BILLMASTER_BILLABLECHARGE_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
